    {
        try
        {
            return await _context.CatalogItems.AnyAsync(ci => ci.Id == id, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error checking if catalog item exists");
            throw;
        }
    }
